screens[6]=['Alertas',`<div class="stack">${card('Temperatura fuera de rango',`${badge('Prioridad alta','bad')}<p style="margin-top:16px">Estanque 03 · 21 °C<br>Hace 2 minutos</p>${btn('Ver detalle y atender')}`)}${card('Mantenimiento de sensor',`${badge('En curso','pending')}<p style="margin-top:16px">Estanque 01 · Revisión programada</p>${btn('Ver seguimiento','alt')}`)}</div>`,'Alertas'];
