screens[9]=['Crear cuenta',`${field('Nombre completo','Administrador de muestra')}${field('Correo electrónico','admin@ejemplo.invalid')}${field('Contraseña','••••••••')}<div class="actions">${btn('Crear cuenta')}${btn('Ya tengo una cuenta','alt')}</div>`,'AUTH'];
