function doc(title,body,classes=''){return `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>${esc(title)}</title><style>${css}</style></head><body class="${classes}">${body}</body></html>`;}
async function main(){fs.mkdirSync(output,{recursive:true});fs.mkdirSync(source,{recursive:true});const {chromium}=load('playwright');const browser=await chromium.launch({headless:true});const errors=[];const result=[];try{for(const spec of specs){const file=path.join(source,`${spec.name}.html`);fs.writeFileSync(file,doc(spec.title,spec.html,spec.classes));const page=await browser.newPage({viewport:{width:spec.width,height:1000},deviceScaleFactor:1});page.on('pageerror',e=>errors.push(`${spec.name}: ${e.message}`));await page.goto(pathToFileURL(file).href);await page.evaluate(()=>document.fonts.ready);const qa=await page.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth,brokenImages:[...document.images].filter(i=>!i.complete||i.naturalWidth===0).map(i=>i.getAttribute('src')),font:document.fonts.check('16px Inter')}));if(qa.scroll>qa.width||qa.brokenImages.length||!qa.font)errors.push({name:spec.name,...qa});await page.screenshot({path:path.join(output,`${spec.name}.png`),fullPage:true});result.push({name:spec.name,title:spec.title,width:spec.width,...qa});await page.close();}fs.writeFileSync(path.join(source,`manifest-${group}.json`),JSON.stringify(result,null,2)+'\n');if(group==='all'){for(const g of ['style','landing','wireframes','wireflows']){const subset=result.filter(m=>g==='style'?['style-guide-trace','information-architecture'].includes(m.name):g==='landing'?m.name.startsWith('Landing'):g==='wireflows'?m.name.startsWith('wireflow'):m.name.startsWith('wireframe')||m.name.startsWith('state-'));fs.writeFileSync(path.join(source,`manifest-${g}.json`),JSON.stringify(subset,null,2)+'\n');}const sections=[['Guía y arquitectura',m=>['style-guide-trace','information-architecture'].includes(m.name)],['Landing desktop y móvil',m=>m.name.startsWith('Landing')],['Pantallas principales y responsive',m=>m.name.startsWith('wireframe')],['Estados y vistas complementarias',m=>m.name.startsWith('state-')],['Wireflows por objetivo',m=>m.name.startsWith('wireflow')]];const body=`<main class="gallery"><span class="eyebrow">Paquete E · Rúbens Fitzgerald Bendezu · TP1</span><h1 style="margin-top:12px">YakuControl + YakuTrace</h1><p>Fuentes editables y PNG de la propuesta UX/UI. Datos ilustrativos. Esta galería no implementa operaciones del servicio.</p><p><a href="README.md">Reproducción</a> · <a href="REVISION_PAQUETE_E.md">Revisión</a> · <a href="GUION_SUSTENTACION.md">Sustentación</a></p>${sections.map(([title,filter])=>`<h2 style="margin-top:40px">${title}</h2><div class="gallerygrid">${result.filter(filter).map(m=>`<a class="card" href="${m.name}.html"><img src="../../assets/images/cap6/${m.name}.png" alt="${esc(m.title)}"/><p>${esc(m.title)}<br><small>${m.width} px · abrir fuente</small></p></a>`).join('')}</div>`).join('')}</main>`;fs.writeFileSync(path.join(source,'index.html'),doc('Galería UX/UI · YakuControl + YakuTrace',body));}if(errors.length)throw new Error(JSON.stringify(errors,null,2));console.log(`Rendered ${result.length} designs (${group}); no horizontal overflow, broken images or font failures.`);}finally{await browser.close();}}
main().catch(e=>{console.error(e.message);process.exitCode=1;});
